  const exp = [["كاش مع المناديب (سجلات COD غير مورّدة)", sum(v.codHeld, (c) => c.collected), "/admin/cod", `${v.codHeld.length} سجل`], ["مدفوعات أونلاين معلّقة", sum(v.onlineOpen, (p) => p.amount), "/admin/payments", `${v.onlineOpen.length} دفعة`], ["فروق كاش غير محسومة", sum(v.codVar, (c) => Math.abs(c.variance)), "/admin/cod", `${v.codVar.length} فرق`], ["استردادات قيد التنفيذ", sum(v.refundsPending, (r) => r.amount), "/admin/refunds", `${v.refundsPending.length} استرداد`], ["توريدات بانتظار التحقق", sum(v.depPending, (d) => d.amount), "/admin/cod", `${v.depPending.length} توريد`]];
  const expTot = sum(exp, (x) => x[1]);
  const fixPay = (p) => `${gate(can, lockWhy("finance.close"), "أكّد الخصم", "pay-ok", { cls: "sm primary", data: { id: p.id } })}${gate(can, lockWhy("finance.close"), "لم يُخصم", "pay-fail", { cls: "sm", data: { id: p.id } })}`;
  const caseFix = (cs) => { const rf = s.refunds.find((r) => r.caseId === cs.id && r.status === "PENDING_APPROVAL"); const ap = rf && s.approvals.find((a) => a.id === rf.approvalId); if (ap) return TW.canApprove(ap) ? `${TW.btn(`اعتمد استرداد ${m2(rf.amount)}`, "approve", { cls: "sm primary", data: { id: ap.id } })}${TW.btn("ارفض", "reject", { cls: "sm", data: { id: ap.id } })}` : `<span class="lock">${ic("lock", "ic xs")}يحتاج ${esc(needLabel(ap))}</span>`; const c = codOf(cs.orderId); if (c) return gate(can, lockWhy("finance.close"), "سوّي فرق الكاش", "cod-fix", { cls: "sm primary", data: { id: c.id } }); return goBtn(`/admin/case/${cs.id}`, "افتح الحالة"); };
  const steps = [
    { k: "online", t: "مطابقة المدفوعات الأونلاين", d: `كل دفعة بطاقة/محفظة اتأكدت من البوابة أو اتلغت · ${s.payments.filter((p) => p.status === "SUCCESS" && p.method !== "cod" && !p.reconciled).length} دفعة ناجحة هتتعلّم «مطابقة» مع الاعتماد`, bl: v.onlineOpen.map((p) => ({ t: `${p.id} · ${p.orderId} · ${m2(p.amount)} — نتيجة ${p.gw} معلّقة (EX-PAY-002)`, fix: fixPay(p) })) },
    { k: "cod", t: "مطابقة الكاش", d: `كل فرق كاش له قرار وكل توريد اتحقق منه · ${m2(sum(v.codHeld, (c) => c.collected))} لسه مع المناديب (تعرّض مفتوح، لا يمنع الإقفال)`, bl: [...v.codVar.map((c) => ({ t: `فرق ${sgn(c.variance)} على ${c.orderId} — ${A.rider(c.riderId)} (EX-COD-003)`, fix: gate(can, lockWhy("finance.close"), "حدد المسؤول", "cod-fix", { cls: "sm primary", data: { id: c.id } }) })), ...v.depPending.map((d) => ({ t: `توريد ${d.id} — ${A.rider(d.riderId)} · ${m2(d.amount)} بانتظار تأكيد الاستلام`, fix: gate(can, lockWhy("finance.close"), "تأكيد الاستلام", "dep-verify", { cls: "sm primary", data: { id: d.id } }) }))] },
    { k: "merchant", t: "ترحيل التزامات التجار", d: `مستحق من طلبات اليوم ${m2(v.merchantPayable)} · كشوف مستحقة ${m2(sum(due, (x) => x.net))} (${due.length})${disputes.length ? ` · ${disputes.length} كشف فيه نزاع (لا يمنع الترحيل، يمنع الصرف)` : ""}`, bl: [] },
    { k: "rider", t: "ترحيل مستحقات المناديب", d: `${openRs.length} تسوية مفتوحة بصافي ${m2(v.riderPayable)} — شامل فروق الكاش المحسومة على المناديب`, bl: [] },
    { k: "exceptions", t: "حسم الاستثناءات المالية الجوهرية", d: "مفيش حالة دعم مالية مفتوحة (ناقص/غلط/تالف/فرق كاش/استرداد) — EX-SET-003", bl: v.openCasesMoney.map((cs) => ({ t: `${cs.id} · ${cs.orderId} — ${cs.type} (${cs.status === "PENDING_APPROVAL" ? "بانتظار موافقة" : "قيد التحقيق"})`, fix: caseFix(cs) })) },
  ];
  const doneN = steps.filter((x) => rc[x.k]).length, allDone = doneN === steps.length;
  const toClose = s.orders.filter((o) => ["RECONCILED", "SETTLEMENT_PENDING"].includes(o.fin) && o.status === "DELIVERED" && !(o.caseIds || []).some((id) => (s.cases.find((c) => c.id === id) || {}).status !== "RESOLVED"));
  const todayDelivered = s.orders.filter((o) => o.status === "DELIVERED" && isToday(o.createdAt));
  const notYet = todayDelivered.filter((o) => !toClose.includes(o) && o.fin !== "FINANCIALLY_CLOSED");
  const closedToday = s.orders.filter((o) => o.fin === "FINANCIALLY_CLOSED" && isToday(o.createdAt));
  const why = (o) => ({ COD_COLLECTED: "الكاش لسه مع المندوب — لم يُورّد", RECON_REQUIRED: "فرق كاش بدون قرار", PAID: "مدفوع — بانتظار التسليم/التسوية", PARTIALLY_REFUNDED: "استرداد جزئي — يُقفل يدوياً بعد المراجعة", REFUNDED: "مسترد بالكامل" }[o.fin] || ((o.caseIds || []).length ? "حالة دعم مفتوحة" : TW.stLabel("fin", o.fin)));
  return `${A.head("المطابقة اليومية والإقفال", `اليوم المالي ${TW.dateAr(Date.now())} — لا يُقفل قبل مطابقة الأونلاين والكاش وترحيل التزامات التجار والمناديب وحسم الاستثناءات`)}
  ${rc.closedAt ? `<div class="banner ok">${ic("check", "ic sm")}<div><b>اليوم المالي مقفل</b> — أقفله ${esc(rc.closedBy)} الساعة ${clock(rc.closedAt)}. ${closedToday.length} طلب من طلبات اليوم بقت «مقفل مالياً». أي حركة بعد الإقفال تترحّل لليوم التالي وتظهر هنا كتعرّض جديد.</div></div>` : ""}
  <div class="fa-top">
    <section class="card fa-exp"><div class="lbl">التعرّض المالي المفتوح (Open Financial Exposure)</div><div class="fa-big num ${expTot > 0 ? "" : "zero"}">${m2(v.exposure)}</div><p class="muted">فلوس لسه مش في إيد توّا أو لسه مش محسومة — كل بند قابل للتتبع لسجلاته.</p>
      ${TW.hbars(exp.map(([l, val, , sub]) => ({ label: l, value: val, sub, tone: "accent" })), { fmt: m2 })}
      <div class="row wrap" style="margin-top:8px">${exp.filter((x) => x[1] > 0).map(([l, , to]) => goBtn(to, l.split(" (")[0])).join("")}</div>
      <p class="fa-foot">${Math.abs(expTot - v.exposure) < 0.01 ? chip("مجموع البنود = التعرّض", "ok", "check") : chip("فرق في التجميع", "bad")}<span class="muted"> · نقدية المحافظ الفعلية مع المناديب ${m2(sum(s.riders, (r) => r.cash))}</span></p></section>
    <section class="card"><h3>${ic("scale", "ic sm")} الالتزامات المرحّلة</h3><dl class="kv fa-kv"><dt>للتجار من طلبات اليوم (بعد العمولة)</dt><dd class="num">${m2(v.merchantPayable)}</dd><dt>كشوف تجار مستحقة</dt><dd class="num">${m2(sum(due, (x) => x.net))} · ${due.length} كشف</dd><dt>للمناديب (تسويات مفتوحة)</dt><dd class="num">${m2(v.riderPayable)} · ${openRs.length} مندوب</dd><dt>استردادات بانتظار التنفيذ</dt><dd class="num">${m2(sum(v.refundsPending, (r) => r.amount))}</dd></dl>
      <hr class="sep"><div class="row wrap">${goBtn("/admin/merchant-settlements", "تسويات التجار")}${goBtn("/admin/rider-settlements", "تسويات المناديب")}${goBtn("/admin/refunds", "الاستردادات")}</div></section>
  </div>
  <section class="card" data-hl="recon-steps"><div class="hd"><h3>${ic("list", "ic sm")} قائمة الإقفال</h3><div class="row wrap">${chip(`${doneN}/${steps.length} خطوات`, allDone ? "ok" : "warn")}${TW.meter(doneN, steps.length, allDone ? "ok" : "brand")}</div></div>
    <ol class="fa-steps">${steps.map((x, i) => { const st = rc[x.k] ? "done" : x.bl.length ? "blocked" : "ready"; return `<li class="fa-step ${st}"><span class="n">${rc[x.k] ? ic("check", "ic xs") : i + 1}</span><div class="grow"><div class="row wrap between"><b>${esc(x.t)}</b>${st === "done" ? chip(`اعتمدها ${rc[x.k].by} · ${clock(rc[x.k].at)}`, "ok", "check") : st === "blocked" ? chip(`${x.bl.length} عائق`, "bad", "alert") : chip("جاهزة للاعتماد", "info")}</div><p class="muted">${esc(x.d)}</p>
      ${!rc[x.k] && x.bl.length ? `<ul class="fa-bl">${x.bl.map((b) => `<li><span class="grow">${esc(b.t)}</span><span class="row wrap">${b.fix}</span></li>`).join("")}</ul>` : ""}
      ${!rc[x.k] && !rc.closedAt ? `<div class="row" style="margin-top:6px">${x.bl.length ? `<button type="button" class="btn sm" disabled title="احسم العوائق الأول">${ic("lock", "ic sm")}<span>اعتمد الخطوة</span></button>` : A.permBtn("finance.close", "اعتمد الخطوة", "rc-step", { cls: "sm primary", icon: "check", data: { step: x.k } })}</div>` : ""}</div></li>`; }).join("")}</ol>
    <div class="fa-close">${rc.closedAt ? chip(`مقفل — ${rc.closedBy} · ${clock(rc.closedAt)}`, "ok", "lock") : allDone ? (can ? confirmBtn(inst, "recon-close", "أقفل اليوم المالي", "rc-close", { cls: "accent", icon: "lock", yes: "أقفل اليوم نهائياً" }) : A.permBtn("finance.close", "أقفل اليوم المالي", "rc-close")) : `<button type="button" class="btn" disabled title="اعتمد كل الخطوات الأول">${ic("lock", "ic sm")}<span>أقفل اليوم المالي</span></button>`}<span class="muted fa-note">${rc.closedAt ? "الإقفال نهائي ومسجّل في سجل التدقيق." : `الإقفال هينقل ${toClose.length} طلب مطابق إلى «مقفل مالياً» ويتسجل في التدقيق.`}</span></div></section>
  <div class="grid g2">${card(rc.closedAt ? `طلبات اتقفلت مالياً اليوم (${closedToday.length})` : `هتتقفل مالياً مع الإقفال (${toClose.length})`, "check", tbl([{ label: "الطلب", render: (o) => A.orderLink(o.id) }, { label: "التشغيل", render: (o) => A.st("order", o.status) }, { label: "المالي", render: (o) => A.st("fin", o.fin) }, { label: "القيمة", num: true, render: (o) => m2(o.totals.total) }], rc.closedAt ? closedToday : toClose, { empty: rc.closedAt ? "لا طلبات" : "مفيش طلبات مطابقة جاهزة للإقفال بعد — التوريد والتحقق بيحركوها" }))}
    ${card(`طلبات اليوم المسلّمة ولن تُقفل (${notYet.length})`, "clock", tbl([{ label: "الطلب", render: (o) => A.orderLink(o.id) }, { label: "المالي", render: (o) => A.st("fin", o.fin) }, { label: "السبب", render: (o) => esc(why(o)) }, { label: "القيمة", num: true, render: (o) => m2(o.totals.total) }], notYet, { empty: "كل طلبات اليوم المسلّمة مطابقة" }) + `<p class="fa-foot muted">دي بتفضل مفتوحة وتترحّل — مش بتختفي. الكاش اللي مع المندوب بيتقفل لما يتورّد ويتحقق.</p>`)}</div>`;
